#[cfg(test)]
fn assert_recovered_constraints_in_tets(
    tets: &[[usize; 4]],
    facets: &[RecoveredFacet],
    stage: &str,
) {
    let edges = tet_edge_set(tets);
    if let Some(edge) = missing_constraint_edge(facets, &edges) {
        panic!("{stage}: recovered constraint edge {edge:?} is missing from retained tets");
    }

    let faces = tet_face_set(tets);
    for facet in facets {
        let face = sorted3(facet.nodes);
        assert!(
            faces.contains(&face),
            "{stage}: recovered constraint facet {face:?} is missing from retained tets"
        );
    }
}

