fn edge_cavity_fixture_points(degree: usize) -> Vec<Point> {
    let mut points = Vec::with_capacity(degree + 2);
    for idx in 0..degree {
        let theta = (idx as f64) * std::f64::consts::TAU / degree as f64;
        points.push(Point::new_3d(theta.cos(), theta.sin(), 0.0));
    }
    points.push(Point::new_3d(0.0, 0.0, 1.0));
    points.push(Point::new_3d(0.0, 0.0, -1.0));
    points
}
