#[test]
fn retriangulate_nm_removes_degree_five_edge_cavity() {
    let degree = 5;
    let points = edge_cavity_fixture_points(degree);
    let upper = degree;
    let lower = degree + 1;
    let tets: Vec<_> = (0..degree)
        .map(|idx| oriented_test_tet(&points, [upper, lower, idx, (idx + 1) % degree]))
        .collect();
    let old_boundary = boundary_faces(tets.iter().copied());
    let mut recovery = FlipRecoveryMesh::new(points, tets);
    let result =
        recovery.try_remove_edge_nm(sorted2([upper, lower]), &HashSet::new(), &HashSet::new());
    assert!(matches!(result, Some((FlipKind::RetriangulateNm, _))));
    assert_eq!(recovery.tets.len(), 6);
    assert!(!recovery.edge_set().contains(&sorted2([upper, lower])));
    assert_eq!(boundary_faces(recovery.tets.iter().copied()), old_boundary);
    assert_eq!(recovery.topology.edge_set(), tet_edge_set(&recovery.tets));
    assert_eq!(recovery.topology.face_set(), tet_face_set(&recovery.tets));
}
