#[test]
fn constrained_surface_carves_closed_internal_shell_and_preserves_marker() {
    let cube = |min: f64, max: f64| {
        vec![
            Point::new_3d(min, min, min),
            Point::new_3d(max, min, min),
            Point::new_3d(max, max, min),
            Point::new_3d(min, max, min),
            Point::new_3d(min, min, max),
            Point::new_3d(max, min, max),
            Point::new_3d(max, max, max),
            Point::new_3d(min, max, max),
        ]
    };
    let faces = |offset: usize, marker: i32| {
        [
            [0, 2, 1],
            [0, 3, 2],
            [4, 5, 6],
            [4, 6, 7],
            [0, 1, 5],
            [0, 5, 4],
            [1, 2, 6],
            [1, 6, 5],
            [2, 3, 7],
            [2, 7, 6],
            [3, 0, 4],
            [3, 4, 7],
        ]
        .into_iter()
        .map(|nodes| SurfaceFacet {
            nodes: nodes.map(|node| node + offset),
            marker: Some(marker),
        })
        .collect::<Vec<_>>()
    };
    let mut points = cube(-1.0, 1.0);
    points.extend(cube(-0.25, 0.25));
    let mut facets = faces(0, 10);
    facets.extend(faces(8, 20));
    let config = TetrahedralizeConfig {
        max_smooth_iterations: 0,
        add_interior_points: false,
        lloyd_iterations: 0,
        preserve_surface: true,
        max_ratio: 1.5,
    };
    let mesh = tetrahedralize_surface_with_facets(&points, &facets, &config)
        .expect("nested closed surfaces tetrahedralize");
    assert!(mesh.boundaries.iter().any(|boundary| boundary.marker == 10));
    assert!(mesh.boundaries.iter().any(|boundary| boundary.marker == 20));
    for element in &mesh.elements {
        let vertices = element.vertices();
        let centroid = vertices.iter().fold([0.0; 3], |mut sum, &node| {
            sum[0] += mesh.nodes[node].x * 0.25;
            sum[1] += mesh.nodes[node].y * 0.25;
            sum[2] += mesh.nodes[node].z * 0.25;
            sum
        });
        assert!(
            centroid.iter().any(|coordinate| coordinate.abs() >= 0.25),
            "retained tetrahedron centroid lies in carved inner shell: {centroid:?}"
        );
    }
}
