#[test]
fn checked_point_cloud_rejects_pathological_inputs_without_running_kernel() {
    let cfg = TetrahedralizeConfig {
        max_smooth_iterations: 0,
        add_interior_points: false,
        lloyd_iterations: 0,
        preserve_surface: false,
        max_ratio: 1.5,
    };
    let cases = [
        (vec![], TetrahedralizationInputError::EmptyPointSet),
        (
            vec![
                Point::new_3d(0.0, 0.0, 0.0),
                Point::new_3d(1.0, 0.0, 0.0),
                Point::new_3d(0.0, 1.0, 0.0),
            ],
            TetrahedralizationInputError::InsufficientPoints {
                provided: 3,
                required: 4,
            },
        ),
        (
            vec![
                Point::new_3d(0.0, 0.0, 0.0),
                Point::new_3d(1.0, 0.0, 0.0),
                Point::new_3d(0.0, 1.0, 0.0),
                Point::new_3d(0.0, 0.0, 1.0),
                Point::new_3d(0.0, 0.0, 1.0),
            ],
            TetrahedralizationInputError::DuplicatePoint {
                first: 3,
                second: 4,
            },
        ),
        (
            vec![
                Point::new_3d(0.0, 0.0, 0.0),
                Point::new_3d(1.0, 0.0, 0.0),
                Point::new_3d(0.0, 1.0, 0.0),
                Point::new_3d(1.0, 1.0, 0.0),
            ],
            TetrahedralizationInputError::DegeneratePointSet,
        ),
        (
            vec![
                Point::new_3d(0.0, 0.0, 0.0),
                Point::new_3d(1.0, 0.0, 0.0),
                Point::new_3d(0.0, 1.0, 0.0),
                Point::new_3d(f64::NAN, 0.0, 1.0),
            ],
            TetrahedralizationInputError::NonFinitePoint { index: 3 },
        ),
    ];
    for (points, expected) in cases {
        let error = tetrahedralize_points_checked(&points, &cfg)
            .expect_err("pathological point cloud must be rejected");
        let TetrahedralizationError::InvalidInput { diagnostics } = error else {
            panic!("expected invalid-input diagnostics");
        };
        assert!(
            diagnostics.errors.contains(&expected),
            "expected {expected:?}, got {:?}",
            diagnostics.errors
        );
    }
}
