#[test]
fn neighbor_pointers_are_symmetric_on_box_mesh() {
    let mut delaunay = Delaunay3D::new();
    let mut points = Vec::new();
    for k in 0..3 {
        for j in 0..3 {
            for i in 0..3 {
                points.push(Point::new_3d(i as f64, j as f64, k as f64));
            }
        }
    }
    for p in &points {
        delaunay.add_point(*p);
    }
    delaunay.tetrahedralize();
    for (idx, slot) in delaunay.tets.iter().enumerate() {
        let Some(tet) = slot else { continue };
        for face_idx in 0..4 {
            let Some(nbr) = tet.neighbors[face_idx] else {
                continue;
            };
            let nbr_tet = delaunay.tets[nbr].as_ref().expect("neighbour live");
            let back_count = nbr_tet
                .neighbors
                .iter()
                .filter(|n| **n == Some(idx))
                .count();
            assert_eq!(
                back_count, 1,
                "tet {idx} face {face_idx} -> {nbr}, but {nbr} has {back_count} back-pointers to {idx}",
            );
        }
    }
}
