#[test]
fn cavity_anchor_visibility_requires_every_outer_half_space() {
    let points = vec![
        Point::new_3d(0.0, 0.0, 0.0),
        Point::new_3d(1.0, 0.0, 0.0),
        Point::new_3d(0.0, 1.0, 0.0),
        Point::new_3d(0.0, 0.0, 1.0),
    ];
    let tets = vec![[0, 1, 2, 3]];
    let remove = vec![0];
    assert!(cavity_anchor_sees_boundary(
        &points,
        &tets,
        &remove,
        Point::new_3d(0.2, 0.2, 0.2),
    ));
    assert!(!cavity_anchor_sees_boundary(
        &points,
        &tets,
        &remove,
        Point::new_3d(0.8, 0.8, 0.8),
    ));
}
#[test]
fn facet_cavity_retriangulation_recovers_coplanar_interior_split() {
    let points = vec![
        Point::new_3d(0.0, 0.0, 0.0),
        Point::new_3d(1.0, 0.0, 0.0),
        Point::new_3d(0.0, 1.0, 0.0),
        Point::new_3d(0.25, 0.25, 0.0),
        Point::new_3d(0.0, 0.0, 1.0),
        Point::new_3d(0.0, 0.0, -1.0),
    ];
    let tets = vec![
        [0, 1, 3, 4],
        [1, 2, 3, 4],
        [2, 0, 3, 4],
        [0, 3, 1, 5],
        [1, 3, 2, 5],
        [2, 3, 0, 5],
    ];
    let mut recovery = FlipRecoveryMesh::new(points, tets);
    let facet = RecoveredFacet {
        nodes: [0, 1, 2],
        marker: 1,
    };
    assert!(!recovery.face_set().contains(&sorted3(facet.nodes)));
    assert!(recovery.try_retriangulate_facet_cavity(facet, &HashSet::new(), &HashSet::new(),));
    assert_eq!(recovery.non_star_cavity_rejections, 0);
    assert!(recovery.face_set().contains(&sorted3(facet.nodes)));
    assert!(
        recovery
            .tets
            .iter()
            .all(|tet| orient_tet_indices(&recovery.points, *tet).is_some())
    );
}
#[doc = " A coplanar annular cap is recovered through its existing Delaunay"]
#[doc = " tiling before edge subdivision. This prevents the former Steiner"]
#[doc = " cascade around the inner ring from obscuring a valid constraint"]
#[doc = " partition."]
#[test]
fn constrained_surface_recovers_annular_coplanar_facet_split() {
    let (points, surface_facets) = annular_plate_fixture();
    let cfg = constrained_test_config();
    let mesh = tetrahedralize_surface_with_facets(&points, &surface_facets, &cfg)
        .expect("annular fixture must recover its constrained surface");
    assert!(mesh.num_elements() > 0);
    let boundary_faces: HashSet<[usize; 3]> = mesh
        .boundaries
        .iter()
        .map(|b| sorted3([b.nodes[0], b.nodes[1], b.nodes[2]]))
        .collect();
    let node_pos = |idx: usize| mesh.nodes[idx];
    for &z in &[0.0_f64, 0.3] {
        let covered: usize = boundary_faces
            .iter()
            .filter(|face| face.iter().all(|&idx| (node_pos(idx).z - z).abs() < 1e-12))
            .count();
        assert!(
            covered >= 8,
            "cap at z={z} has only {covered} boundary faces"
        );
    }
    let boundary_edges: HashSet<[usize; 2]> = mesh
        .boundaries
        .iter()
        .flat_map(|b| {
            let n = &b.nodes;
            [
                sorted2([n[0], n[1]]),
                sorted2([n[1], n[2]]),
                sorted2([n[2], n[0]]),
            ]
        })
        .collect();
    for facet in &surface_facets {
        for (u, v) in [
            (facet.nodes[0], facet.nodes[1]),
            (facet.nodes[1], facet.nodes[2]),
            (facet.nodes[2], facet.nodes[0]),
        ] {
            let (pu, pv) = (points[u], points[v]);
            let covered = boundary_edges.iter().any(|&e| {
                let pe0 = mesh.nodes[e[0]];
                let pe1 = mesh.nodes[e[1]];
                let collinear = {
                    let d = vec_from(pu, pv);
                    let w = vec_from(pu, pe0);
                    norm3(cross3(d, w)) < 1e-9 * norm3(d).max(1e-12)
                };
                collinear && {
                    let t0 = dot3(vec_from(pu, pe0), vec_from(pu, pv));
                    let t1 = dot3(vec_from(pu, pe1), vec_from(pu, pv));
                    t0.min(t1) < dot3(vec_from(pu, pv), vec_from(pu, pv)) && t0.max(t1) > 0.0
                }
            });
            assert!(
                covered,
                "input facet edge {u}-{v} is not tiled by boundary edges"
            );
        }
    }
}
#[doc = " A re-entrant tube/wall junction shares the same coplanar annular cap"]
#[doc = " path and must retain the port footprint after constrained recovery."]
#[test]
fn constrained_surface_recovers_reentrant_tube_wall_junction() {
    let (points, surface_facets) = tube_wall_junction_fixture();
    let cfg = constrained_test_config();
    let mesh = tetrahedralize_surface_with_facets(&points, &surface_facets, &cfg)
        .expect("junction fixture must recover its constrained surface");
    assert!(mesh.num_elements() > 0);
    let cap_faces = mesh
        .boundaries
        .iter()
        .filter(|b| {
            b.nodes
                .iter()
                .all(|&idx| (mesh.nodes[idx].z - 1.0).abs() < 1e-12)
        })
        .count();
    assert!(
        cap_faces >= 8,
        "box top annulus has only {cap_faces} boundary faces"
    );
}
#[doc = " Coplanar tiled constraint surfaces are accepted as a real constrained"]
#[doc = " mesh, never as the degraded unconstrained recovery result."]
#[test]
fn constrained_surface_accepts_preexisting_coplanar_tilings() {
    let cfg = constrained_test_config();
    let (annulus_points, annulus_facets) = annular_plate_fixture();
    tetrahedralize_surface_with_facets(&annulus_points, &annulus_facets, &cfg)
        .expect("annular tiling must recover as a constrained mesh");
    let (junction_points, junction_facets) = tube_wall_junction_fixture();
    tetrahedralize_surface_with_facets(&junction_points, &junction_facets, &cfg)
        .expect("tube/wall tiling must recover as a constrained mesh");
}
